import React, { useEffect, useState } from 'react';
import productsApi from '../../api/productsApi';
import ProductList from './component/productList/productList';


ProductsFeature.propTypes = {};

function ProductsFeature(props) {
  const [dataList, setDataList] = useState([]);

  useEffect(() => {
    const fetchProducts = async () => {
      const params = {
        _limit: 10,
      };
      const producList = await productsApi.getAll(params);
      setDataList(producList);
      console.log(producList);
    };
    fetchProducts();
  }, []);

  return (
    <div>
      <h1>Product List</h1>
      <div><button type="button" class="btn btn-primary">Primary</button></div>
      <div>
        <ProductList dataList={dataList} />
      </div>
    </div>
  );
}

export default ProductsFeature;
