import { Button } from '@material-ui/core';
import { makeStyles } from '@material-ui/core/styles';
import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { decrease, increase } from './counterSlice';

CounterFeater.propTypes = {};

function CounterFeater(props) {
  const useStyles = makeStyles({
    root: {
      background: 'linear-gradient(180deg, rgba(237, 232, 232 , 1) 20%, #999 50%)',
      border: 0,
      borderRadius: 3,
      boxShadow: '0 3px 5px 2px rgba(4, 68, 206, 0)',
      color: '#e5dede',
      height: 48,
      padding: '0 30px',
      margin: '2rem',
      '&:hover': {
        background: 'linear-gradient(180deg, rgba(237, 232, 232 , 0.5) 20%, #999 50%)',
        color: '#fff',
        boxShadow: '0 3px 5px 2px rgba(4, 68, 206, .3)',
      },
    },

    mm: {
      display: 'flex',
      justifyContent: 'center',
      padding: '2rem',
    },
  });

  const dispatch = useDispatch();
  const count = useSelector((state) => state.count);

  const handleIncreaseClick = () => {
    const action = increase();
    console.log(action);
    dispatch(action);
  };

  const handleDecreaseClick = () => {
    const action = decrease();
    console.log(action);
    dispatch(action);
  };

  const classes = useStyles();
  return (
    <div>
      <div>
        <h1>Counter Feature</h1>
      </div>
      <div>count : {count}</div>
      <div className={classes.mm}>
        <div>
          <Button className={classes.root} onClick={handleIncreaseClick}>
            Increase
          </Button>
        </div>
        <div>
          <Button className={classes.root} onClick={handleDecreaseClick}>
            Decrease
          </Button>
        </div>
      </div>
    </div>
  );
}

export default CounterFeater;
