import React from 'react';
import Album from '../album';
import './list-style.scss';

AlbumList.propTypes = {};

AlbumList.defaultProps = {
  albumList: [],
};

function AlbumList({ albumList }) {
  return (
    <div className="album_list">
      {albumList.map((item) => (
        <div key={item.id}>
          <Album album={item} />
        </div>
      ))}
    </div>
  );
}

export default AlbumList;
