import React from 'react';
import { Route, Switch } from 'react-router-dom';
import './App.css';
import Header from './components/header';
import MenuComponent from './components/menu';
import AlbumFeature from './features/album';
import CounterFeater from './features/counter';
import MemberFeature from './features/member';
import ProductsFeature from './features/products';
import TodoFeature from './features/todo';

function App() {
  return (
    <div className="App">
      <Header />
      <MenuComponent />
      <div>
        <Switch>
          <Route path="/" component={CounterFeater} exact />
          <Route path="/todo" component={TodoFeature} />
          <Route path="/album" component={AlbumFeature} />
          <Route path="/member" component={MemberFeature} />
          <Route path="/products" component={ProductsFeature} />
        </Switch>
      </div>
    </div>
  );
}

export default App;
