import { Button } from '@material-ui/core';
import queryString from 'query-string';
import React, { useEffect, useState } from 'react';
import { useHistory, useLocation, useRouteMatch } from 'react-router';
import MemberList from './components/memberlist/memberlist';
import '../../styles/main.css';


MemberFeature.propTypes = {};

function MemberFeature(props) {
  const initlist = [
    {
      id: 1,
      name: 'tran van hung',
      phone: '023658779',
      status: 'best',
    },
    {
      id: 2,
      name: 'ly van tung',
      phone: '12132132',
      status: 'bad',
    },
    {
      id: 3,
      name: 'nguyen thi giau',
      phone: '023658779',
      status: 'good',
    },
    {
      id: 4,
      name: 'luong hieu my',
      phone: '02154654',
      status: 'best',
    },
    {
      id: 5,
      name: 'tran thien nhan',
      phone: '045465656',
      status: 'best',
    },
    {
      id: 6,
      name: 'do thi thanh ',
      phone: '456456645',
      status: 'good',
    },
    {
      id: 7,
      name: 'lam van tung',
      phone: '12132132',
      status: 'bad',
    },
    {
      id: 8,
      name: 'ung van hung',
      phone: '088888849',
      status: 'good',
    },
    {
      id: 9,
      name: 'tran thi manh',
      phone: '09899898989',
      status: 'best',
    },
    {
      id: 10,
      name: 'la thanh thanh',
      phone: '08989888555',
      status: 'best',
    },
  ];

  const location = useLocation();
  const history = useHistory();
  const match = useRouteMatch();

  // eslint-disable-next-line no-unused-vars
  const [memberList, setMemberList] = useState(initlist);
  const [filterList, setFilterList] = useState(() => {
    const pagams = queryString.parse(location.search);
    return pagams.status || 'all';
  });

  useEffect(() => {
    const params = queryString.parse(location.search);
    setFilterList(params.status || 'all');
  }, [location.search]);

  const onClickShowAll = () => {
    //setFilterList('all');
    const queryParams = { status: 'all' };
    history.push({
      pathname: match.path,
      search: queryString.stringify(queryParams),
    });
  };

  const onClickShowBest = () => {
    //setFilterList('best');
    const queryParams = { status: 'best' };
    history.push({
      pathname: match.path,
      search: queryString.stringify(queryParams),
    });
  };

  const onClickShowGood = () => {
    // setFilterList('good');
    const queryParams = { status: 'good' };
    history.push({
      pathname: match.path,
      search: queryString.stringify(queryParams),
    });
  };

  const onClickShowBad = () => {
    // setFilterList('bad');
    const queryParams = { status: 'bad' };
    history.push({
      pathname: match.path,
      search: queryString.stringify(queryParams),
    });
  };

  const renderMemberList = memberList.filter(
    (member) => filterList === 'all' || filterList === member.status
  );

  return (
    <div>
      <div className='member_button'>
           <button className="btn btn-primary" onClick={onClickShowAll}> Show All</button>
           <button className="btn btn-secondary" onClick={onClickShowBest}> Show Best</button>
           <button className="btn btn-success" onClick={onClickShowGood}> Show Good</button>
           <button className="btn btn-warning" onClick={onClickShowBad}> Show Bad</button>
           <Button color="primary">Hello World</Button>
           <Button color="primary">Hello World</Button>
      </div>
      <hr></hr>
      <div className="member_space">
        <MemberList memberList={renderMemberList} />
      </div>
    </div>
  );
}

export default MemberFeature;
